    PaymentAttempt = apps.get_model("dic", "PaymentAttempt")
    database = schema_editor.connection.alias

    for order in Order.objects.using(database).iterator():
        order_items = list(
            OrderItem.objects.using(database)
            .filter(order_id=order.pk)
            .order_by("pk")
        )
        total = sum((item.fee_snapshot_ngn for item in order_items), 0)
        revision = PriceRevision.objects.using(database).create(
            order_id=order.pk,
            revision_number=1,
            early_bird_cutoff_at=None,
            total_amount_ngn=total,
            created_at=order.created_at,
            accepted_at=order.created_at,
        )
        PriceItem.objects.using(database).bulk_create(
            [
                PriceItem(
                    revision_id=revision.pk,
                    order_item_id=item.pk,
                    category_name_snapshot=item.category_name_snapshot,
                    early_bird_fee_snapshot_ngn=None,
                    regular_fee_snapshot_ngn=item.fee_snapshot_ngn,
                    fee_snapshot_ngn=item.fee_snapshot_ngn,
                    price_type="regular",
                )
                for item in order_items
            ]
        )
        Order.objects.using(database).filter(pk=order.pk).update(
            current_price_revision_id=revision.pk
        )
        PaymentAttempt.objects.using(database).filter(order_id=order.pk).update(
            price_revision_id=revision.pk
        )


